package dev.zomboid.gore;
import java.lang.reflect.*;import java.util.*;
public final class R {
 static final Map<String,Class<?>> TYPES=new java.util.concurrent.ConcurrentHashMap<>();
 // Reflect only members actually used; eager setAccessible on JDK internals is prohibited by Java modules.
 static final ClassValue<Map<String,Field>> FIELDS=new ClassValue<>(){protected Map<String,Field> computeValue(Class<?> c){return new java.util.concurrent.ConcurrentHashMap<>();}};
 static final ClassValue<Map<String,Map<Integer,List<Method>>>> METHODS=new ClassValue<>(){protected Map<String,Map<Integer,List<Method>>> computeValue(Class<?> c){Map<String,Map<Integer,List<Method>>> map=new HashMap<>();Set<Method> seen=new HashSet<>();for(Class<?> k=c;k!=null;k=k.getSuperclass())for(Method m:k.getDeclaredMethods())if(seen.add(m))map.computeIfAbsent(m.getName(),n->new HashMap<>()).computeIfAbsent(m.getParameterCount(),n->new ArrayList<>()).add(m);for(Method m:c.getMethods())if(seen.add(m))map.computeIfAbsent(m.getName(),n->new HashMap<>()).computeIfAbsent(m.getParameterCount(),n->new ArrayList<>()).add(m);return map;}};
 public static Class<?> type(String name){return TYPES.computeIfAbsent(name,n->{try{return Class.forName(n);}catch(ClassNotFoundException e){throw new IllegalStateException(n,e);}});}
 static Class<?> boxed(Class<?> c){if(c==int.class)return Integer.class;if(c==float.class)return Float.class;if(c==double.class)return Double.class;if(c==long.class)return Long.class;if(c==boolean.class)return Boolean.class;return c;}
 static boolean matches(Class<?>[] types,Object[] args){for(int i=0;i<types.length;i++)if(args[i]==null?types[i].isPrimitive():!boxed(types[i]).isInstance(args[i]))return false;return true;}
 public static Object call(Object receiver,String name,Object... args){Class<?> c=receiver instanceof Class<?>?(Class<?>)receiver:receiver.getClass();try{List<Method> list=METHODS.get(c).getOrDefault(name,Collections.emptyMap()).getOrDefault(args.length,List.of());for(Method m:list)if(list.size()==1||matches(m.getParameterTypes(),args)){m.setAccessible(true);return m.invoke(receiver instanceof Class<?>?null:receiver,args);}throw new NoSuchMethodException(c.getName()+"."+name);}catch(InvocationTargetException e){throw new IllegalStateException(name,e.getCause());}catch(ReflectiveOperationException e){throw new IllegalStateException(name,e);}}
 static Field field(Class<?> c,String name){return FIELDS.get(c).computeIfAbsent(name,n->{for(Class<?> k=c;k!=null;k=k.getSuperclass())try{Field f=k.getDeclaredField(n);f.setAccessible(true);return f;}catch(NoSuchFieldException ignored){}throw new IllegalStateException(c.getName()+"."+n);});}
 public static Object get(Object receiver,String name){try{return field(receiver instanceof Class<?>?(Class<?>)receiver:receiver.getClass(),name).get(receiver instanceof Class<?>?null:receiver);}catch(IllegalAccessException e){throw new IllegalStateException(name,e);}}
 public static void set(Object receiver,String name,Object value){try{field(receiver instanceof Class<?>?(Class<?>)receiver:receiver.getClass(),name).set(receiver instanceof Class<?>?null:receiver,value);}catch(IllegalAccessException e){throw new IllegalStateException(name,e);}}
 public static Object make(String name,Object... args){try{for(Constructor<?> c:type(name).getDeclaredConstructors())if(c.getParameterCount()==args.length&&matches(c.getParameterTypes(),args)){c.setAccessible(true);return c.newInstance(args);}throw new NoSuchMethodException(name);}catch(ReflectiveOperationException e){throw new IllegalStateException(name,e);}}
 public static double num(Object o){return ((Number)o).doubleValue();}public static boolean yes(Object o){return Boolean.TRUE.equals(o);}
}
